    \"\"\"Send private text prompts to OpenAI's Responses API.\"\"\"

    def __init__(self, api_key=None, api_url=DEFAULT_API_URL):
        self.api_key = api_key or os.environ.get(\"OPENAI_API_KEY\")
        if not self.api_key:
            raise ValueError(\"OpenAI API key required. Pass api_key or set OPENAI_API_KEY.\")
        self.api_url = api_url

    def send_text(self, prompt, model=\"gpt-4o\", instructions=None):
        \"\"\"Send a private text prompt and return the response dict.\"\"\"
        payload = {
            \"model\": model,
            \"input\": prompt,
        }
        if instructions is not None:
            payload[\"instructions\"] = instructions

        data = json.dumps(payload).encode(\"utf-8\")
        headers = {
            \"Content-Type\": \"application/json\",
            \"Authorization\": f\"Bearer {self.api_key}\",
        }

        req = urllib.request.Request(
            self.api_url,
            data=data,
            headers=headers,
            method=\"POST\",
        )

        # Use default SSL context (no custom cert overrides)
        try:
            with urllib.request.urlopen(req) as resp:
                return json.loads(resp.read().decode(\"utf-8\"))
        except HTTPError as exc:
            body = exc.read().decode(\"utf-8\", errors=\"replace\")
            raise RuntimeError(f\"OpenAI API error {exc.code}: {body}\") from exc
        except URLError as exc:
            raise RuntimeError(f\"OpenAI API connection error: {exc.reason}\") from exc
